def transform(g):
    # remove the large solid 3 cluster(s); they are overlaid noise replacing
    # the underlying 4x4 motif in the otherwise symmetric pattern.
    out=[r[:] for r in g]
    for i,row in enumerate(g):
        for j,v in enumerate(row):
            if v==3:
                # reconstruct via 180-degree symmetry of clean surrounding pattern
                out[i][j]=g[15-i][15-j]
    return out
